    } else if (detail && typeof detail === 'object' && detail.message) {
      // 409 冲突等结构化错误
      err.userMessage = detail.message
      err.conflict = detail
    } else {
      err.userMessage = err.message || '请求失败'
    }
    return Promise.reject(err)
  }
)

